package com.mikael8367.nexustech.nuclear;
public class IdentityScramTest {
 static int pass,fail; interface Case {void run() throws Exception;}
 static void ck(boolean b,String m){if(!b)throw new AssertionError(m);}
 static void run(String n,Case c){try{c.run();pass++;System.out.println("PASS "+n);}catch(Throwable e){fail++;System.out.println("FAIL "+n+": "+e);}}
 static boolean flag(FakeTile t,String name) throws Exception {java.lang.reflect.Field f=FakeTile.class.getDeclaredField(name);f.setAccessible(true);return f.getBoolean(t);}
 static FakeTile base(){FakeTile t=new FakeTile();t.enabled=true;t.fuelTicks=10;t.tank.amount=10;t.indicator=true;return t;}
 public static void main(String[] args){
  run("replaced after failing callback: never change replacement or dirty stale tile",()->{FakeTile t=base(),replacement=base();int[] calls={0};t.onDirty=()->{calls[0]++;t.world.current=replacement;throw new IllegalStateException("original");};try{t.setAutoTemperatureTarget(500);throw new AssertionError("missing exception");}catch(IllegalStateException e){ck(e.getMessage().equals("original"),"lost exception");}ck(replacement.indicator,"replacement indicator modified");ck(calls[0]==1,"stale dirty called");ck(flag(t,"pendingScramIndicator")&&flag(t,"pendingScramDirty"),"unperformed notification not pending");ck(!t.enabled&&t.scrammed,"not latched");});
  run("unloaded after failure retains both notifications until loaded",()->{FakeTile t=base();int[] calls={0};t.onDirty=()->{calls[0]++;t.world.loaded=false;throw new IllegalStateException("original");};try{t.setAutoTemperatureTarget(500);}catch(IllegalStateException expected){}ck(flag(t,"pendingScramIndicator")&&flag(t,"pendingScramDirty"),"unloaded notification counted as done");ck(calls[0]==1&&t.indicator,"notification attempted unloaded");t.onDirty=null;t.world.loaded=true;t.update();ck(!flag(t,"pendingScramIndicator")&&!flag(t,"pendingScramDirty")&&!t.indicator,"retry did not run");});
  run("replacement during indicator callback keeps dirty pending",()->{FakeTile t=base(),replacement=base();int[] dirty={0};t.onIndicator=()->{t.world.current=replacement;};t.onDirty=()->dirty[0]++;t.tank.amount=0;t.setAutoTemperatureEnabled(true);ck(replacement.indicator,"replacement indicator changed");ck(dirty[0]==0,"dirty ran after replacement");ck(flag(t,"pendingScramIndicator")&&flag(t,"pendingScramDirty"),"notification completed despite replacement");});
  run("healthy trip clears notifications",()->{FakeTile t=base();int[] dirty={0};t.onDirty=()->dirty[0]++;t.tank.amount=0;t.setAutoTemperatureEnabled(true);ck(!t.indicator&&dirty[0]>0&&!flag(t,"pendingScramIndicator")&&!flag(t,"pendingScramDirty"),"healthy notification incomplete");});
  run("latched abort while stopped notifies",()->{FakeTile t=base();t.enabled=false;int[] dirty={0};t.onDirty=()->dirty[0]++;java.lang.reflect.Method m=FakeTile.class.getDeclaredMethod("abortUnsafeStart",boolean.class);m.setAccessible(true);m.invoke(t,true);ck(t.scrammed&&!t.enabled&&dirty[0]>0&&!t.indicator,"missing abort notification");});
  run("structure visual exception still notifies SCRAM",()->{FakeTile t=base();int[] dirty={0};t.onDirty=()->dirty[0]++;t.onVisual=()->{throw new IllegalStateException("visual");};java.lang.reflect.Method m=FakeTile.class.getDeclaredMethod("stopForStructureLoss");m.setAccessible(true);try{m.invoke(t);throw new AssertionError("missing visual failure");}catch(java.lang.reflect.InvocationTargetException e){ck(e.getCause().getMessage().equals("visual"),"wrong failure");}ck(t.scrammed&&!t.enabled&&dirty[0]>0&&!t.indicator,"failure prevented notification");});
  run("failed block write stays pending",()->{FakeTile t=base();t.world.rejectSet=true;t.tank.amount=0;t.setAutoTemperatureEnabled(true);ck(t.indicator&&flag(t,"pendingScramIndicator"),"rejected write counted as complete");t.world.rejectSet=false;t.update();ck(!t.indicator&&!flag(t,"pendingScramIndicator"),"write retry missing");});
  run("structure failure with replacement protects new controller",()->{FakeTile t=base(),r=base();int[] dirty={0};t.onDirty=()->dirty[0]++;t.onVisual=()->{t.world.current=r;throw new IllegalStateException("visual");};java.lang.reflect.Method m=FakeTile.class.getDeclaredMethod("stopForStructureLoss");m.setAccessible(true);try{m.invoke(t);}catch(java.lang.reflect.InvocationTargetException expected){}ck(r.indicator&&dirty[0]==0&&flag(t,"pendingScramDirty")&&flag(t,"pendingScramIndicator"),"replacement or pending damaged");});
  System.out.println("RESULT passed="+pass+" failed="+fail);if(fail>0)System.exit(1);
 }
}
